rules:
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --bg: #07090D; --bg-2: #0A0D13; --surface: #0D1118; --surface-2: #11161F; --surface-3: #161C27; --line: #1A212D; --line-2: #242D3C; --ink: #EDF2F9; --ink-2: #A2AEC1; --ink-3: #6A768A; --ink-4: #434E61; --brand: #7B7BFF; --brand-2: #A78BFA; --brand-soft: rgba(123, 123, 255, .13); --brand-line: rgba(123, 123, 255, .35); --bull: #19E58C; --bull-soft: rgba(25, 229, 140, .11); --bear: #FF4D67; --bear-soft: rgba(255, 77, 103, .11); --amber: #FFB020; --amber-soft: rgba(255, 176, 32, .12); --sky: #45B8FF; --sky-soft: rgba(69, 184, 255, .12); --pink: #F472B6; --pink-soft: rgba(244, 114, 182, .12); --teal: #2DD4BF; --teal-soft: rgba(45, 212, 191, .11); --violet: #A78BFA; --violet-soft: rgba(167, 139, 250, .13); --shadow-1: 0 1px 0 rgba(255, 255, 255, .025) inset, 0 1px 2px rgba(0, 0, 0, .35); --shadow-2: 0 18px 40px -16px rgba(0, 0, 0, .7), 0 1px 0 rgba(255, 255, 255, .03) inset; --shadow-pop: 0 30px 70px -20px rgba(0, 0, 0, .85), 0 0 0 1px rgba(255, 255, 255, .04); --glass: rgba(13, 17, 24, .72); --focus: 0 0 0 3px rgba(123, 123, 255, .3); color-scheme: dark; }
}

@keyframes pop { 
  0% { opacity: 0; transform: translateY(-4px) scale(0.98); }
  100% { opacity: 1; transform: none; }
}

@keyframes rise { 
  0% { opacity: 0; transform: translateY(14px) scale(0.985); }
  100% { opacity: 1; transform: none; }
}

@media (min-width: 901px) {
  body.rail .side { --w: 68px; }
  body.rail .side .brand-mark b, body.rail .side .nav-label, body.rail .nav a span, body.rail .nav a .count, body.rail .nav a .chip, body.rail .nav .live-pill, body.rail .me .who, body.rail .side-foot .mkt-text { display: none; }
  body.rail .side-top { padding: 0px; justify-content: center; flex-direction: column; height: auto; gap: 8px; }
  body.rail .side-collapse { margin: 0px; }
  body.rail .nav a { justify-content: center; padding: 0px; }
  body.rail .nav-label { height: 10px; padding: 0px; }
  body.rail .side-foot .row { justify-content: center; flex-direction: column; }
  body.rail .theme-toggle { flex-direction: column; }
  body.rail .theme-toggle::before { width: 30px; }
  body.rail .theme-toggle[data-mode="dark"]::before { transform: translateY(28px); }
  body.rail .me { justify-content: center; padding: 6px 0px; }
  body.rail .side-collapse .ic { transform: rotate(180deg); }
  body.rail .back-link span { display: none; }
  body.rail .back-link { justify-content: center; padding: 0px; }
}

@media (min-width: 901px) {
  .side { --w: calc(244px + env(safe-area-inset-left, 0px)); padding-left: calc(12px + env(safe-area-inset-left, 0px)); }
  body.rail .side { --w: calc(68px + env(safe-area-inset-left, 0px)); }
}

@media (max-width: 1380px) {
  .topbar:has(.sec-tabs) { flex-wrap: wrap; row-gap: 10px; }
  .topbar .ttl:has(.sec-tabs) { display: contents; }
  .topbar:has(.sec-tabs) .sub { flex: 1 1 0%; min-width: 0px; }
  .topbar:has(.sec-tabs) .actions { margin-left: auto; }
  .topbar .sec-tabs { order: 1; width: 100%; overflow-x: auto; scrollbar-width: none; }
  .topbar .sec-tabs::-webkit-scrollbar { display: none; }
  .topbar .sec-tabs a { flex: 1 0 auto; justify-content: center; }
}

@media (max-width: 560px) {
  .topbar .sec-tabs a { padding: 0px 10px; }
  .topbar:has(.sec-tabs) .actions .btn { width: 38px; padding: 0px; font-size: 0px; gap: 0px; }
}

@media (max-width: 900px) {
  .side { position: fixed; left: 0px; top: 0px; bottom: 0px; transform: translateX(-102%); background: var(--surface); box-shadow: var(--shadow-pop); --w: calc(272px + env(safe-area-inset-left, 0px)) !important; }
  body.menu-open .side { transform: none; }
  body.menu-open .scrim { display: block; position: fixed; inset: 0px; z-index: 25; background: rgba(8, 11, 18, 0.4); }
  .side { padding: calc(14px + env(safe-area-inset-top, 0px)) 12px calc(12px + env(safe-area-inset-bottom, 0px)) calc(12px + env(safe-area-inset-left, 0px)); }
  .side-foot .mkt { max-width: calc(100% - 68px); }
  .side-foot .mkt .mkt-text { min-width: 0px; overflow: hidden; text-overflow: ellipsis; }
  .side-collapse { display: none; }
  .topbar { padding: 12px 16px; min-height: 60px; }
  .topbar .menu-btn { display: inline-flex; }
  .topbar h1 { font-size: 18px; }
  .topbar .sub { display: none; }
  .page { padding: 4px 16px 40px; }
  .cols-2, .cols-3, .cols-4 { grid-template-columns: minmax(0px, 1fr); }
  body.flush .main { display: flex; flex-direction: column; height: 100dvh; background: var(--ob-bg, var(--bg)); }
  body.flush .page { flex: 1 1 0%; min-height: 0px; height: auto; width: 100%; margin: 0px; }
  body.flush .topbar.obbar { display: flex; flex: 0 0 auto; position: relative; gap: 8px; min-height: 0px; height: calc(48px + env(safe-area-inset-top, 0px)); padding: env(safe-area-inset-top, 0px) max(10px, env(safe-area-inset-right, 0px)) 0 max(6px, env(safe-area-inset-left, 0px)); background: var(--ob-glass, var(--glass)); border-bottom-color: var(--ob-line, var(--line)); }
  .obbar .ttl { gap: 9px; flex: 0 0 auto; }
  .obbar h1 { font-size: 17px; }
  .obbar .actions { flex: 1 1 auto; min-width: 0px; gap: 6px; flex-wrap: nowrap; }
  .obbar .menu-btn { width: 40px; height: 40px; flex: 0 0 auto; }
  .obbar .mkt { height: 26px; padding: 0px 10px; min-width: 0px; overflow: hidden; }
  .obbar .mkt .mkt-text { min-width: 0px; overflow: hidden; text-overflow: ellipsis; }
  .obbar .mkt:empty { display: none; }
  .obbar .theme-toggle { flex: 0 0 auto; }
  .obbar .theme-toggle button::after { content: ""; position: absolute; inset: -7px -1px; }
  .obbar .avatar-btn { width: 40px; height: 40px; padding: 0px; flex: 0 0 auto; border: 0px; border-radius: 50%; background: none; display: grid; place-items: center; cursor: pointer; transition: background 0.15s; }
  .obbar .avatar-btn:hover { background: var(--surface-3); }
  .obbar .avatar-btn .avatar { width: 30px; height: 30px; }
  .topbar.obbar .actions a.btn.unlock-btn { flex: 0 0 auto; height: 32px; padding: 0px 11px; gap: 6px; border-radius: 10px; font-size: 13px; }
}

@media (max-width: 380px) {
  body.flush .topbar.obbar { gap: 6px; }
  .obbar .mkt-w { display: none; }
  .topbar.obbar .actions a.btn.unlock-btn { width: 32px; padding: 0px; justify-content: center; }
  .topbar.obbar .actions a.btn.unlock-btn span { display: none; }
}

@media (max-width: 356px) {
  .obbar .mkt { width: 26px; padding: 0px; justify-content: center; }
  .obbar .mkt .mkt-text { display: none; }
}

@media (min-width: 901px) {
  body.rail .nav a .ic.nav-lock, body.rail .side-unlock .su-t, body.rail .side-unlock .su-go { display: none; }
  body.rail .side-unlock { justify-content: center; padding: 4px 0px; border-color: transparent; background: none; box-shadow: none; }
}

@keyframes lockRing { 
  0% { opacity: 0.9; transform: scale(0.92); }
  75%, 100% { opacity: 0; transform: scale(1.3); }
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) body.flush { --ob-bg: #04060A; --ob-ink: #EEF3FA; --ob-ink-2: #9AA8BD; --ob-glow: rgba(25, 229, 140, .06); --ob-green: #19E58C; --ob-green-soft: rgba(25, 229, 140, .12); --ob-glass: rgba(10, 15, 23, .85); --ob-line: #1A2433; --ob-amber: #FFB020; --ob-amber-soft: rgba(255, 176, 32, .15); }
}

@media (max-width: 900px) {
  .terminal { display: flex; flex-direction: column; }
  .terminal iframe { flex: 1 1 0%; min-height: 0px; height: auto; }
  .ob-status { position: relative; z-index: 1; order: -1; flex: 0 0 auto; right: auto; bottom: auto; justify-content: center; height: 28px; padding: 0px 14px; border-top: 0px; border-right: 0px; border-left: 0px; border-image: none; border-bottom: 1px solid var(--ob-line); border-radius: 0px; backdrop-filter: none; background: linear-gradient(var(--ob-amber-soft), var(--ob-amber-soft)), var(--ob-bg); color: var(--ob-ink); }
  .ob-status #obStatusText { min-width: 0px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
